<script setup lang="ts">
import{ref,reactive,onMounted}from'vue';import{http}from'../../api/http';import RecordPage from '../../components/RecordPage.vue';import type {Definition,Row} from '../../shared/records'
const weights=reactive<Row>({nutritionWeight:'0.4',preferenceWeight:'0.25',reviewWeight:'0.2',historyWeight:'0.15'}),version=ref(0),error=ref(''),success=ref(''),pending=ref(false),targets=reactive<Row>({})
const metrics=[['caloriesKcal','能量 kcal'],['proteinGrams','蛋白质 g'],['fatGrams','脂肪 g'],['carbGrams','碳水 g'],['sodiumMg','钠 mg']]
const definition:Definition={title:'疾病饮食禁忌规则',endpoint:'/diet-rules',detail:'',columns:[['diseaseCode','疾病标签'],['targetType','禁止对象'],['targetValue','目标食材或菜品编号']],fields:[{key:'diseaseCode',label:'疾病标签（与老人档案一致）'},{key:'targetType',label:'禁止对象',type:'select',options:[{value:'INGREDIENT',label:'食材'},{value:'DISH',label:'菜品编号'}],initial:'INGREDIENT'},{key:'targetValue',label:'食材名称或菜品编号'}]}
onMounted(async()=>{try{const config=await http.get<never,Row>('/recommendation-config');Object.keys(weights).forEach(k=>weights[k]=config[k]);version.value=config.version;for(const [key]of metrics)targets[key!]={min:config.targets?.[key!]?.min??'',max:config.targets?.[key!]?.max??''}}catch(e){error.value=(e as Error).message}})
async function save(){pending.value=true;error.value='';try{const selected:Row={};for(const[key]of metrics)if(targets[key!].min!==''&&targets[key!].max!=='')selected[key!]=targets[key!];const config=await http.put<never,Row>('/recommendation-config',{...weights,targets:selected});version.value=config.version;success.value='参数已生效'}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
</script>
<template><section><h1>膳食推荐参数</h1><p>当前生效版本：{{version}}。先排除已登记禁忌，再按权重排序；规则须经专业核对。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="success" :title="success" type="success" :closable="false"/><form class="content-card form-stack" @submit.prevent="save"><template v-for="(label,key) in {nutritionWeight:'营养适配权重',preferenceWeight:'偏好权重',reviewWeight:'评价权重',historyWeight:'历史选择权重'}" :key="key"><label :for="'weight-'+key">{{label}}</label><el-input :id="'weight-'+key" v-model="weights[key]" type="number" step="any"/></template><h3>营养目标区间（可选，每份）</h3><div v-for="[key,label] in metrics" :key="key" class="toolbar"><span>{{label}}</span><el-input v-if="targets[key!]" v-model="targets[key!].min" placeholder="下限" type="number" step="any" :aria-label="label+'下限'"/><el-input v-if="targets[key!]" v-model="targets[key!].max" placeholder="上限" type="number" step="any" :aria-label="label+'上限'"/></div><el-button native-type="submit" type="primary" :loading="pending">保存参数并生效</el-button></form><RecordPage :definition="definition"><template #actions="{row,action}"><el-button link type="danger" @click="action('DELETE',`/diet-rules/${row.id}`)">停用规则</el-button></template></RecordPage></section></template>
